function getEnv(name: string, fallback: string): string {
  try {
    const deno = (globalThis as { Deno?: { env?: { get?: (n: string) => string | undefined } } }).Deno;
    const fromDeno = deno?.env?.get?.(name);
    if (fromDeno !== undefined) return fromDeno;
  } catch {
    /* node test env */
  }
  try {
    return (typeof process !== "undefined" ? process.env?.[name] : undefined) ?? fallback;
  } catch {
    return fallback;
  }
}

function getEnvInt(name: string, fallback: number): number {
  const v = Number(getEnv(name, String(fallback)));
  return Number.isFinite(v) && v > 0 ? Math.floor(v) : fallback;
}

// --- Server-managed settings (env with sane defaults) ----------------------
export const QWEN_BASE_URL = getEnv("QWEN_BASE_URL", "https://evolve-eternity-epidural.ngrok-free.dev/v1").replace(/\/+$/, "");
export const QWEN_MODEL = getEnv("QWEN_MODEL", "qwen3:4b-instruct-2507-q4_K_M");
export const QWEN_API_KEY = getEnv("QWEN_API_KEY", "local");
/** Optional real gateway auth (e.g. "Basic dXNlcjpwYXNz" or "Bearer x") for a protected tunnel. */
export const QWEN_GATEWAY_AUTH = getEnv("QWEN_GATEWAY_AUTH", "");
export const QWEN_TIMEOUT_MS = getEnvInt("QWEN_TIMEOUT_MS", 100000);
export const QWEN_MAX_INPUT_CHARS = getEnvInt("QWEN_MAX_INPUT_CHARS", 8000);
export const QWEN_MAX_TOKENS = getEnvInt("QWEN_MAX_TOKENS", 1600);

export type QwenErrorCode = "MODEL_UNAVAILABLE" | "MODEL_OUTPUT_INVALID" | "VALIDATION_ERROR" | "INPUT_TOO_LARGE";

export class QwenError extends Error {
  constructor(public code: QwenErrorCode, message: string) {
    super(message);
    this.name = "QwenError";
  }
}

// ---------------------------------------------------------------------------
// Untrusted-content handling (resume intake)
// ---------------------------------------------------------------------------

const INSTRUCTION_PATTERNS: RegExp[] = [
  /\bignore\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context|messages?|output)\b/gi,
  /\bdisregard\s+(?:(?:all|any|the|your|previous|prior|above|system|developer)\s+)*(?:instructions?|prompts?|rules?|context)\b/gi,
  /\bdo\s+not\s+(?:follow|obey|listen\s+to)\b/gi,
  /\byou\s+are\s+now\b/gi,
  /\bsystem\s+prompt\b/gi,
  /\bdeveloper\s+message\b/gi,
  /\bjailbreak\b/gi,
  /\boverride\s+(?:(?:your|the|system|developer)\s+)*(?:instructions?|rules?|prompt)\b/gi,
  /\bpretend\s+(?:to\s+|that\s+|you\s+)/gi,
  /\bsay\s+you\s+(?:are|have|would|can)\b/gi,
  /\bgive\s+(?:me\s+)?(?:a\s+)?100\s*%?\s*(?:match|fit|score)\b/gi,
  /\balways\s+(?:ignore|follow|obey)\b/gi,
  /\breveal\s+(?:your|the)\s+(?:system|instructions?|prompt)\b/gi,
];

/** Neutralize instruction-like phrases in untrusted resume text. */
export function sanitizeUntrusted(text: string): string {
  let out = String(text ?? "");
  for (const re of INSTRUCTION_PATTERNS) out = out.replace(re, "[redacted]");
  return out.trim();
}

/** Explicit delimiter marking untrusted content for the model. */
export function wrapUntrusted(text: string): string {
  return `<untrusted_input>\n${text}\n</untrusted_input>`;
}

// ---------------------------------------------------------------------------
// Strict JSON extraction — never salvage arbitrary brace substrings blindly.
// ---------------------------------------------------------------------------

export function isHtmlInterstitial(content: string): boolean {
  const head = String(content ?? "").slice(0, 400).trim().toLowerCase();
  return /^<!doctype|^<html|ngrok|502 bad gateway|504 gateway time-out|cloudflare/.test(head);
}

export function extractJsonStrict(content: string): unknown {
  const trimmed = String(content ?? "").trim();
  if (!trimmed) throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: empty completion");
  if (isHtmlInterstitial(trimmed)) {
    throw new QwenError("MODEL_UNAVAILABLE", "qwen: gateway returned an HTML/interstitial response (infrastructure error, not model output).");
  }
  // 1) strict full parse
  try {
    return JSON.parse(trimmed);
  } catch {
    /* fall through */
  }
  // 2) strip markdown fences
  const fenced = trimmed.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
  try {
    return JSON.parse(fenced);
  } catch {
    /* fall through */
  }
  // 3) balanced object extraction (only if the remainder is clearly a JSON object)
  const start = fenced.indexOf("{");
  const end = fenced.lastIndexOf("}");
  if (start !== -1 && end > start) {
    const candidate = fenced.slice(start, end + 1);
    // Reject if non-whitespace noise precedes the object or trails it.
    const prefixNoise = fenced.slice(0, start).trim();
    const suffixNoise = fenced.slice(end + 1).trim();
    if (prefixNoise.length <= 40 && suffixNoise.length <= 40) {
      try {
        return JSON.parse(candidate);
      } catch {
        throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: unbalanced JSON in response.");
      }
    }
  }
  throw new QwenError("MODEL_OUTPUT_INVALID", `qwen: no valid JSON object in response (${trimmed.slice(0, 160)}…)`);
}

// ---------------------------------------------------------------------------
// Sanitized telemetry — never log raw prompts.
// ---------------------------------------------------------------------------

function logMetric(entry: Record<string, string | number>) {
  console.log(`[qwen] ${Object.entries(entry).map(([k, v]) => `${k}=${v}`).join(" ")}`);
}

// ---------------------------------------------------------------------------
// OpenAI-compatible chat call
// ---------------------------------------------------------------------------

export async function callQwen(params: {
  system: string;
  user: string;
  json?: boolean;
  maxTokens?: number;
  temperature?: number;
  task?: string;
  timeoutMs?: number;
}): Promise<unknown> {
  const task = params.task ?? "generic";
  const started = Date.now();
  const inputChars = String(params.user ?? "").length;

  if (inputChars > QWEN_MAX_INPUT_CHARS) {
    logMetric({ task, status: "rejected", reason: "input_too_large", input_chars: inputChars });
    throw new QwenError("INPUT_TOO_LARGE", `Input exceeds the ${QWEN_MAX_INPUT_CHARS} character limit.`);
  }

  const messages: { role: string; content: string }[] = [
    { role: "system", content: params.system },
    { role: "user", content: params.user },
  ];
  const body: Record<string, unknown> = {
    model: QWEN_MODEL,
    messages,
    temperature: params.temperature ?? 0.2,
    max_tokens: params.maxTokens ?? QWEN_MAX_TOKENS,
    stream: false,
  };
  if (params.json) body.response_format = { type: "json_object" };

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${QWEN_API_KEY}`,
  };
  if (QWEN_GATEWAY_AUTH) headers["Authorization"] = QWEN_GATEWAY_AUTH;

  const attempt = async (repairHint: boolean): Promise<unknown> => {
    const controller = new AbortController();
    const timeoutMs = params.timeoutMs ?? QWEN_TIMEOUT_MS;
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let res: Response;
    try {
      res = await fetch(`${QWEN_BASE_URL}/chat/completions`, {
        method: "POST",
        headers,
        body: JSON.stringify(repairHint ? { ...body, messages: [...messages, { role: "user", content: "IMPORTANT: respond with ONLY valid JSON and nothing else. No markdown fences, no prose." }] } : body),
        signal: controller.signal,
      });
    } catch (err) {
      const timedOut = err instanceof Error && err.name === "AbortError";
      throw new QwenError("MODEL_UNAVAILABLE", timedOut ? `qwen: request timed out after ${timeoutMs}ms` : `qwen: network error (is the endpoint reachable?): ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      clearTimeout(timer);
    }

    if (!res.ok) {
      const text = await res.text();
      if (isHtmlInterstitial(text)) {
        throw new QwenError("MODEL_UNAVAILABLE", "qwen: gateway returned an HTML/interstitial response (infrastructure error).");
      }
      throw new QwenError("MODEL_UNAVAILABLE", `qwen: HTTP ${res.status}: ${text.slice(0, 300)}`);
    }

    const data = await res.json();
    const content = data?.choices?.[0]?.message?.content;
    if (typeof content !== "string" || content.length === 0) {
      throw new QwenError("MODEL_OUTPUT_INVALID", "qwen: empty completion");
    }
    if (!params.json) return content;

    const usage = data?.usage;
    const latency = Date.now() - started;
    try {
      const parsed = extractJsonStrict(content);
      logMetric({
        task, status: "ok", latency_ms: latency,
        model: QWEN_MODEL, out_chars: content.length,
        tokens_in: usage?.prompt_tokens ?? 0, tokens_out: usage?.completion_tokens ?? 0,
        input_chars: inputChars,
      });
      return parsed;
    } catch (err) {
      if (err instanceof QwenError) {
        if (err.code === "MODEL_OUTPUT_INVALID" && !repairHint) {
          // Exactly one controlled repair attempt.
          logMetric({ task, status: "repair", latency_ms: latency, reason: err.message.slice(0, 80) });
          return attempt(true);
        }
        logMetric({ task, status: "failed", latency_ms: latency, code: err.code });
        throw err;
      }
      throw err;
    }
  };

  return attempt(false);
}


// ---------------------------------------------------------------------------
// WorkSense Grounded Policy engine — DETERMINISTIC retrieval, zero LLM.
//  - paragraph-level policy chunks (stable doc_code + section heading)
//  - BM25-style relevance scoring (no LLM credits)
//  - calibrated abstention gate evaluated BEFORE any model call
//  - citation validator so an ungrounded answer can never slip through
// ---------------------------------------------------------------------------

export interface PolicyDoc {
  id: string;
  title: string;
  category: string;
  doc_code: string;
  version?: number;
  effective_date?: string;
  effective_from?: string;
  effective_to?: string | null;
  applicable_locations?: string[];
  applicable_worker_types?: string[];
  supersedes_doc_id?: string | null;
  summary?: string;
  sections: { code: string; heading: string; text: string }[];
}

export interface PolicyChunk {
  doc_code: string;
  doc_title: string;
  category: string;
  doc_id?: string;
  version?: number;
  effective_from?: string;
  effective_to?: string | null;
  section_code: string;
  heading: string;
  text: string;
}

export interface RetrievedChunk extends PolicyChunk {
  score: number;
}

/** Calibrated on the seeded policy corpus. Questions below this skip the LLM. */
export const ABSTENTION_THRESHOLD = 0.75;

const STOPWORDS = new Set([
  "a", "an", "the", "to", "of", "in", "on", "for", "and", "or", "with", "is", "are", "be", "at",
  "by", "from", "as", "it", "its", "i", "you", "your", "we", "our", "can", "may", "must", "will",
  "not", "no", "that", "this", "these", "those", "per", "up", "over", "if", "when", "who", "what",
  "which", "how", "do", "does", "did", "have", "has", "had", "would", "should", "could", "about",
  "all", "any", "each", "every", "more", "most", "other", "some", "such", "than", "then", "there",
  "they",   "their", "into", "within", "after", "before", "during", "between", "out", "off", "under",
  "above", "does", "s", "t",
]);

export function tokenize(text: string): string[] {
  return String(text ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9\s'-]/g, " ")
    .split(/\s+/)
    .map((t) => t.replace(/^['-]+|['-]+$/g, ""))
    .filter((t) => t.length > 1 && !STOPWORDS.has(t));
}

export function flattenPolicies(policies: PolicyDoc[]): PolicyChunk[] {
  const chunks: PolicyChunk[] = [];
  for (const p of policies) {
    for (const s of p.sections) {
      chunks.push({
        doc_id: p.id,
        doc_code: p.doc_code,
        doc_title: p.title,
        category: p.category,
        version: p.version,
        effective_from: p.effective_from ?? p.effective_date,
        effective_to: p.effective_to ?? null,
        section_code: s.code,
        heading: s.heading,
        text: s.text,
      });
    }
  }
  return chunks;
}

export interface EmployeePolicyContext {
  location?: string;
  worker_type?: string;
}

/** Normalize an applicability list; "All" matches anything. */
function appliesTo(list: string[] | undefined, value: string | undefined): boolean {
  if (!value) return true; // unknown field: do not filter (clarification handles it)
  const norm = (v: string) => v.trim().toLowerCase();
  const arr = (list ?? ["All"]).map(norm);
  return arr.includes("all") || arr.includes(norm(value));
}

/** Is the document applicable given the known employee context? Unknown fields
 *  are treated as "not ruled out" — the missing-field logic decides if we must
 *  clarify instead of assume. */
export function applicabilityOk(doc: PolicyDoc, ctx: EmployeePolicyContext): boolean {
  return appliesTo(doc.applicable_locations, ctx.location) && appliesTo(doc.applicable_worker_types, ctx.worker_type);
}

/** Which applicability fields are missing but required by the document? */
export function missingApplicability(doc: PolicyDoc, ctx: EmployeePolicyContext): string[] {
  const missing: string[] = [];
  const needsLocation = (doc.applicable_locations ?? []).length > 0 && !(doc.applicable_locations ?? []).map((v) => v.trim().toLowerCase()).includes("all");
  const needsWorker = (doc.applicable_worker_types ?? []).length > 0 && !(doc.applicable_worker_types ?? []).map((v) => v.trim().toLowerCase()).includes("all");
  if (needsLocation && !ctx.location) missing.push("location");
  if (needsWorker && !ctx.worker_type) missing.push("worker_type");
  return missing;
}

/** Date-window filter: keep docs effective on `asOf`. */
export function filterByWindow(policies: PolicyDoc[], asOf: string): PolicyDoc[] {
  const t = new Date(asOf).getTime();
  return (policies ?? []).filter((p) => {
    const from = p.effective_from ?? p.effective_date;
    if (from && new Date(from).getTime() > t) return false;
    if (p.effective_to && new Date(p.effective_to).getTime() < t) return false;
    return true;
  });
}

/** Docs that fell OUTSIDE the window (used for honest "expired/retired" notes). */
export function filterOutOfWindow(policies: PolicyDoc[], asOf: string): PolicyDoc[] {
  const t = new Date(asOf).getTime();
  return (policies ?? []).filter((p) => {
    const from = p.effective_from ?? p.effective_date;
    if (from && new Date(from).getTime() > t) return true;
    if (p.effective_to && new Date(p.effective_to).getTime() < t) return true;
    return false;
  });
}

/**
 * Resolve the CURRENT version set for an as-of date:
 *  - drop documents outside the date window,
 *  - keep the newest version per doc_code,
 *  - drop documents explicitly superseded by a current document.
 */
export function currentVersionSet(policies: PolicyDoc[], asOf: string): PolicyDoc[] {
  const inWindow = filterByWindow(policies, asOf);
  const byCode = new Map<string, PolicyDoc>();
  for (const doc of inWindow) {
    const cur = byCode.get(doc.doc_code);
    if (!cur || (doc.version ?? 1) > (cur.version ?? 1)) byCode.set(doc.doc_code, doc);
  }
  const current = [...byCode.values()];
  const supersededIds = new Set(
    current.filter((d) => d.supersedes_doc_id).map((d) => d.supersedes_doc_id as string)
  );
  return current.filter((d) => !supersededIds.has(d.id));
}

const K1 = 1.2;
const B = 0.75;

/** Classic BM25 over the flattened chunk corpus. */
export function retrieveChunks(policies: PolicyDoc[], question: string, topK = 3): RetrievedChunk[] {
  const chunks = flattenPolicies(policies);
  const N = chunks.length;
  const avgdl = chunks.reduce((s, c) => s + tokenize(c.text).length, 0) / Math.max(1, N);
  const queryTerms = tokenize(question);

  // document frequency per term
  const df = new Map<string, number>();
  const docTokens = chunks.map((c) => {
    const tokens = tokenize(c.text);
    const uniq = new Set(tokens);
    for (const t of uniq) df.set(t, (df.get(t) ?? 0) + 1);
    return tokens;
  });

  const idf = (term: string) => Math.log(1 + (N - (df.get(term) ?? 0) + 0.5) / ((df.get(term) ?? 0) + 0.5));

  const scored: RetrievedChunk[] = chunks.map((c, i) => {
    const tokens = docTokens[i];
    const dl = tokens.length;
    let score = 0;
    for (const t of queryTerms) {
      const tf = tokens.filter((x) => x === t).length;
      if (tf === 0) continue;
      score += ((tf * (K1 + 1)) / (tf + K1 * (1 - B + (B * dl) / avgdl))) * idf(t);
    }
    return { ...c, score };
  });

  return scored.sort((a, b) => b.score - a.score).slice(0, topK);
}

/** Fuzzy normalization for quote matching (whitespace + case insensitive). */
export function normalizeForMatch(s: string): string {
  return String(s ?? "").toLowerCase().replace(/\s+/g, " ").trim();
}

export interface Citation {
  claim?: string;
  doc_code?: string;
  version?: number | string;
  section?: string;
  exact_quote?: string;
}

export interface CitationValidation {
  valid: Citation[];
  droppedCount: number;
  invalidReasons: string[];
}

/**
 * STRICT citation validation (Phase 7): every exact_quote must appear in the
 * cited SECTION of the cited DOCUMENT — existing verbatim somewhere in the
 * retrieved chunks is NOT sufficient (source identity + claim support).
 * A version may be omitted, in which case any version of the doc_code matches.
 * Invalid citations are dropped with a reason; callers repair once or abstain.
 */
export function validateCitations(
  citations: Citation[] | undefined,
  chunks: RetrievedChunk[]
): CitationValidation {
  const valid: Citation[] = [];
  const invalidReasons: string[] = [];
  let dropped = 0;

  const hasExactSection = (c: Citation, quote: string): boolean =>
    chunks.some((ch) => {
      if (String(ch.doc_code).toLowerCase() !== String(c.doc_code ?? "").toLowerCase()) return false;
      if (String(ch.section_code) !== String(c.section ?? "")) return false;
      if (c.version !== undefined && c.version !== null && String(ch.version ?? "") !== String(c.version)) return false;
      return normalizeForMatch(ch.text).includes(quote);
    });

  for (const c of citations ?? []) {
    const quote = normalizeForMatch(c.exact_quote ?? "");
    if (!quote) {
      dropped++;
      invalidReasons.push("Citation has an empty exact_quote.");
      continue;
    }
    if (!c.doc_code || !c.section) {
      dropped++;
      invalidReasons.push("Citation is missing doc_code or section.");
      continue;
    }
    if (hasExactSection(c, quote)) {
      valid.push(c);
    } else {
      dropped++;
      invalidReasons.push(`Quote not found in the cited section ${c.doc_code} ${c.section}: "${String(c.exact_quote ?? "").slice(0, 80)}"`);
    }
  }
  return { valid, droppedCount: dropped, invalidReasons };
}

/** Highest-scoring match against documents that fell out of the date window —
 *  used to say "this policy was retired on <date>" instead of inventing. */
export function bestExpiredHit(policies: PolicyDoc[], question: string, asOf: string): {
  doc_code: string;
  title: string;
  effective_to: string | null;
  score: number;
} | null {
  const out = filterOutOfWindow(policies, asOf);
  if (out.length === 0) return null;
  const res = retrieveChunks(out, question, 1);
  if (res.length === 0) return null;
  return {
    doc_code: res[0].doc_code,
    title: res[0].doc_title,
    effective_to: res[0].effective_to ?? null,
    score: res[0].score,
  };
}

/**
 * Question tokens that appear in `candidateTexts` but in NONE of `otherTexts`.
 * Used to distinguish "this question is really about the expired/excluded
 * document" from "the question only shares generic words (e.g. reimbursement)
 * with a still-current document".
 */
export function exclusiveQuestionTokens(question: string, candidateTexts: string[], otherTexts: string[]): string[] {
  const q = new Set(tokenize(question));
  const cand = new Set(candidateTexts.flatMap((t) => tokenize(t)));
  const others = new Set(otherTexts.flatMap((t) => tokenize(t)));
  return [...q].filter((t) => cand.has(t) && !others.has(t));
}

// ---------------------------------------------------------------------------
// Phase 9: precedence + conflict handling.
// ---------------------------------------------------------------------------

/** A policy that is in contention for a question (one best chunk per doc). */
export interface PolicyConflictCandidate {
  doc_code: string;
  title: string;
  version: number | undefined;
  section_code: string;
  heading: string;
  score: number;
  effective_from: string | null;
  effective_to: string | null;
}

/**
 * Phase 9 (items 4-5): detect when TWO or more CURRENT, applicable policies are
 * NEARLY TIED for the question — i.e. the second-best family is within a tight
 * ratio of the best. When two different policies match almost equally well,
 * choosing one would be arbitrary, so the caller surfaces the conflict instead
 * of silently picking. A clearly-dominant policy (e.g. the leave doc for an
 * annual-leave question) is not a conflict. Location/worker-type variants
 * (POL-LVE vs POL-LVE-EU) share one family and are resolved by applicability.
 */
export function policyFamily(docCode: string): string {
  return String(docCode ?? "").replace(/-(EU|US|UK|CA|DE|FR|IN|APAC)$/i, "");
}

/** Near-tie ratio: a second family within this fraction of the best is in
 *  contention for the same answer. */
export const CONFLICT_NEAR_TIE_RATIO = 0.9;

export function detectPolicyConflict(
  applicable: PolicyDoc[],
  question: string,
  minScore: number,
  topN = 8
): PolicyConflictCandidate[] {
  const chunks = retrieveChunks(applicable, question, topN);
  const bestByFamily = new Map<string, RetrievedChunk>();
  for (const c of chunks) {
    const family = policyFamily(c.doc_code);
    const cur = bestByFamily.get(family);
    if (!cur || c.score > cur.score) bestByFamily.set(family, c);
  }
  const sorted = [...bestByFamily.values()].sort((a, b) => b.score - a.score);
  const best = sorted[0];
  if (!best || best.score < minScore) return [];
  const contenders = sorted.filter(
    (c) => c.score >= CONFLICT_NEAR_TIE_RATIO * best.score && c.score >= 0.5
  );
  return contenders.map((c) => ({
    doc_code: c.doc_code,
    title: c.doc_title,
    version: c.version,
    section_code: c.section_code,
    heading: c.heading,
    score: +c.score.toFixed(3),
    effective_from: c.effective_from ?? null,
    effective_to: c.effective_to ?? null,
  }));
}

/**
 * Phase 9 (item 4): deterministic precedence when multiple current policies
 * could apply — more specific applicability first, then newer effective date,
 * then doc_code as a stable tiebreaker.
 */
export function resolvePrecedence(policies: PolicyDoc[]): PolicyDoc[] {
  const specificity = (d: PolicyDoc): number => {
    const locs = (d.applicable_locations ?? []).filter((l) => l.toLowerCase() !== "all").length;
    const types = (d.applicable_worker_types ?? []).filter((t) => t.toLowerCase() !== "all").length;
    return locs + types;
  };
  return [...(policies ?? [])].sort((a, b) => {
    const s = specificity(b) - specificity(a);
    if (s !== 0) return s;
    const d = new Date(b.effective_from ?? b.effective_date ?? 0).getTime() - new Date(a.effective_from ?? a.effective_date ?? 0).getTime();
    if (d !== 0) return d;
    return String(a.doc_code).localeCompare(String(b.doc_code));
  });
}


// ---------------------------------------------------------------------------
// Per-task runtime schema + semantic validation for Qwen outputs.
// Runs AFTER generation regardless of provider structured-output support.
// No invalid/partial model output becomes trusted domain data.
// ---------------------------------------------------------------------------

export type ValidationResult = { ok: true } | { ok: false; errors: string[] };

const isStr = (v: unknown): v is string => typeof v === "string";
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const isArr = (v: unknown): v is unknown[] => Array.isArray(v);
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

const TIERS = ["FOUNDATIONAL", "INTERMEDIATE", "ADVANCED", "EXPERT"];
const EVAL_TIERS = ["Red Flag", "Developing", "Competent-Baseline", "Advanced", "Master-Architectural"];
const EVAL_RECS = ["Select", "Move Forward", "Reject"];
const POLICY_STATUS = ["grounded_response", "insufficient_evidence"];
const TREND = ["up", "flat", "down"];
const SIGNOFF = ["HR_EXECUTIVE", "MANAGER"];

function fail(errors: string[]): ValidationResult {
  return errors.length === 0 ? { ok: true } : { ok: false, errors };
}

// 1) Resume Evidence Extraction (6.1)
export function validateResumeExtraction(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.full_name) || d.full_name.trim().length === 0) errors.push("full_name must be a non-empty string");
  if (!isNum(d.years_experience) || d.years_experience < 0 || d.years_experience > 60) errors.push("years_experience must be 0..60");
  const skills = d.extracted_skills;
  if (!isArr(skills)) errors.push("extracted_skills must be an array");
  else {
    for (const raw of skills) {
      const s = isObj(raw) ? raw : null;
      if (!s || !isStr(s.skill_name) || s.skill_name.trim().length === 0 || s.skill_name.length > 80) errors.push("skill_name missing/too long");
      if (!s || !isNum(s.years) || s.years < 0 || s.years > 50) errors.push("skill years out of bounds");
      if (!s || !isStr(s.proficiency_tier) || !TIERS.includes(s.proficiency_tier)) errors.push(`proficiency_tier must be one of ${TIERS.join(",")}`);
      if (!s || !isStr(s.evidence_quote) || s.evidence_quote.length > 200) errors.push("evidence_quote must be a short string");
    }
  }
  if (!isArr(d.verified_projects)) errors.push("verified_projects must be an array");
  return fail(errors);
}

// 2) 5-Tier Interview Rubric (6.2)
export function validateRubric(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.competency) || d.competency.trim().length === 0) errors.push("competency missing");
  if (!isStr(d.question) || d.question.trim().length === 0) errors.push("question missing");
  if (!isArr(d.follow_up_probes) || d.follow_up_probes.length !== 2 || d.follow_up_probes.some((p) => !isStr(p) || p.length === 0)) {
    errors.push("follow_up_probes must contain exactly 2 non-empty strings");
  }
  if (!isObj(d.rubric)) errors.push("rubric must be an object");
  else {
    for (let i = 1; i <= 5; i++) {
      const k = `tier_${i}` as const;
      if (!isStr(d.rubric[k]) || (d.rubric[k] as string).trim().length === 0) errors.push(`rubric.${k} must be a non-empty string`);
    }
  }
  return fail(errors);
}

// 3) Assessment Evaluation
export function validateEvaluation(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isArr(d.evaluations)) errors.push("evaluations must be an array");
  else {
    for (const raw of d.evaluations) {
      const e = isObj(raw) ? raw : null;
      if (!e) { errors.push("evaluation item not an object"); continue; }
      if (!isStr(e.competency) || e.competency.trim().length === 0) errors.push("evaluation competency missing");
      if (!isStr(e.tier) || !EVAL_TIERS.includes(e.tier)) errors.push(`tier must be one of ${EVAL_TIERS.join("|")}`);
      if (!isNum(e.score) || e.score < 1 || e.score > 5 || !Number.isInteger(e.score)) errors.push("score must be an integer 1..5");
      if (!isStr(e.evidence) || e.evidence.trim().length === 0) errors.push("evidence missing (assessment must be evidence-linked)");
    }
  }
  if (!isStr(d.overall_recommendation) || !EVAL_RECS.includes(d.overall_recommendation)) errors.push(`overall_recommendation must be one of ${EVAL_RECS.join("|")}`);
  return fail(errors);
}

// 4) Grounded Policy Answer (6.3)
export function validatePolicyAnswer(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.status) || !POLICY_STATUS.includes(d.status)) errors.push(`status must be one of ${POLICY_STATUS.join("|")}`);
  if (!isStr(d.answer)) errors.push("answer must be a string");
  if (!isArr(d.citations)) errors.push("citations must be an array");
  else {
    for (const raw of d.citations) {
      const c = isObj(raw) ? raw : null;
      if (!c) { errors.push("citation not an object"); continue; }
      if (!isStr(c.doc_code) || !/^POL-/.test(c.doc_code)) errors.push("citation doc_code must start with POL-");
      if (c.version !== undefined && c.version !== null && !isStr(c.version) && !isNum(c.version)) errors.push("citation version must be a string or number");
      if (!isStr(c.section) || c.section.trim().length === 0) errors.push("citation section missing");
      if (!isStr(c.exact_quote) || c.exact_quote.trim().length === 0) errors.push("citation exact_quote must be non-empty");
    }
  }
  return fail(errors);
}

// 5) Performance Narrative
export function validatePerformanceNarrative(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.strengths) || d.strengths.trim().length === 0) errors.push("strengths missing");
  if (!isStr(d.growth_areas) || d.growth_areas.trim().length === 0) errors.push("growth_areas missing");
  if (!isStr(d.trend_direction) || !TREND.includes(d.trend_direction)) errors.push(`trend_direction must be one of ${TREND.join("|")}`);
  if (!isNum(d.confidence) || d.confidence < 0 || d.confidence > 1) errors.push("confidence must be 0..1");
  return fail(errors);
}

// 6) Recommendation Explanation (6.4)
export function validateRecommendationExplanation(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.title) || d.title.trim().length === 0) errors.push("title missing");
  if (!isStr(d.executive_summary) || d.executive_summary.trim().length < 20) errors.push("executive_summary too short");
  if (!isObj(d.proposed_action) || !isStr(d.proposed_action.action_type) || !isStr(d.proposed_action.target_entity_id)) {
    errors.push("proposed_action.action_type/target_entity_id required");
  }
  if (!isStr(d.required_human_signoff_role) || !SIGNOFF.includes(d.required_human_signoff_role)) {
    errors.push(`required_human_signoff_role must be one of ${SIGNOFF.join("|")}`);
  }
  return fail(errors);
}

// 8) Assessment Evaluation (Phase 6) — per-competency judgment block emitted by
// the model. Semantic checks (quotes exist, score bounds vs rubric anchors) run
// in assessment.ts validateJudgmentItem, which has the rubric + answers context.
const ASSESSMENT_JUDGMENTS = ["1", "2", "3", "4", "5", "NOT_ASSESSED", "INSUFFICIENT_EVIDENCE"];

export function validateAssessmentJudgment(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isArr(d.judgments)) errors.push("judgments must be an array");
  else {
    for (const raw of d.judgments) {
      const j = isObj(raw) ? raw : null;
      if (!j) { errors.push("judgment item not an object"); continue; }
      if (!isStr(j.competency) || j.competency.trim().length === 0) errors.push("judgment competency missing");
      if (!isStr(j.judgment) || !ASSESSMENT_JUDGMENTS.includes(j.judgment)) {
        errors.push(`judgment must be one of ${ASSESSMENT_JUDGMENTS.join("|")}`);
      }
      if (!isArr(j.evidence_quotes)) errors.push("judgment evidence_quotes must be an array");
      else if (j.evidence_quotes.some((q) => !isStr(q))) errors.push("evidence_quotes entries must be strings");
      if (j.anchor_ref !== undefined && j.anchor_ref !== null && !isStr(j.anchor_ref)) errors.push("anchor_ref must be a string");
      if (j.uncertainty !== undefined && (!isNum(j.uncertainty) || j.uncertainty < 0 || j.uncertainty > 1)) {
        errors.push("uncertainty must be a number 0..1");
      }
      if (j.suggested_follow_up !== undefined && j.suggested_follow_up !== null && !isStr(j.suggested_follow_up)) {
        errors.push("suggested_follow_up must be a string");
      }
      // Phase 5: dimension scores (correctness/reasoning/trade_offs/communication).
      const dimScores = ["1", "2", "3", "4", "5", "NA"];
      if (j.dimensions !== undefined && j.dimensions !== null) {
        if (!isObj(j.dimensions)) errors.push("dimensions must be an object");
        else {
          for (const [name, v] of Object.entries(j.dimensions as Record<string, unknown>)) {
            if (!["correctness", "reasoning", "trade_offs", "communication"].includes(name)) {
              errors.push(`dimensions.${name} is not a supported dimension`);
            } else if (typeof v !== "string" || !dimScores.includes(v)) {
              errors.push(`dimensions.${name} must be one of ${dimScores.join("|")}`);
            }
          }
        }
      }
    }
  }
  if (!isStr(d.summary) || d.summary.trim().length === 0) errors.push("summary missing");
  return fail(errors);
}

// 7) Rich Resume Review (Phase 4) — the full traceable extraction schema.
export function validateResumeReview(d: unknown): ValidationResult {
  const errors: string[] = [];
  if (!isObj(d)) return { ok: false, errors: ["response is not an object"] };
  if (!isStr(d.full_name) || d.full_name.trim().length === 0) errors.push("full_name must be a non-empty string");

  const contact = d.contact;
  if (contact !== undefined && contact !== null && !isObj(contact)) errors.push("contact must be an object");
  else if (isObj(contact)) {
    for (const k of ["email", "phone", "location", "linkedin"]) {
      if (contact[k] !== undefined && contact[k] !== null && !isStr(contact[k])) errors.push(`contact.${k} must be a string`);
      if (isStr(contact[k]) && (contact[k] as string).length > 200) errors.push(`contact.${k} too long`);
    }
  }

  const checkRoles = (arr: unknown, label: string) => {
    if (!isArr(arr)) {
      errors.push(`${label} must be an array`);
      return;
    }
    for (const raw of arr) {
      const r = isObj(raw) ? raw : null;
      if (!r) {
        errors.push(`${label}: entry must be an object`);
        return;
      }
      if (!isStr(r.title) || r.title.trim().length === 0) errors.push(`${label}: title missing`);
      if (!isStr(r.company)) errors.push(`${label}: company must be a string`);
      if (r.start !== undefined && !isStr(r.start)) errors.push(`${label}: start must be a string`);
      if (r.end !== undefined && !isStr(r.end)) errors.push(`${label}: end must be a string`);
      if (r.years_claimed !== undefined && (!isNum(r.years_claimed) || r.years_claimed < 0 || r.years_claimed > 60)) errors.push(`${label}: years_claimed must be 0..60`);
      if (!isStr(r.quote) || r.quote.trim().length === 0 || r.quote.length > 300) errors.push(`${label}: quote must be a short string`);
    }
  };
  checkRoles(d.roles, "roles");

  const checkSimple = (arr: unknown, label: string, quoteRequired: boolean) => {
    if (!isArr(arr)) {
      errors.push(`${label} must be an array`);
      return;
    }
    for (const raw of arr) {
      const r = isObj(raw) ? raw : null;
      if (!r) {
        errors.push(`${label}: entry must be an object`);
        return;
      }
      const names = label === "education" ? ["institution", "degree", "year"] : label === "certifications" ? ["name", "issuer", "year"] : ["name", "role"];
      for (const k of names) if (!isStr(r[k])) errors.push(`${label}: ${k} must be a string`);
      if (label === "projects") {
        if (!isArr(r.tech_stack)) errors.push(`${label}: tech_stack must be an array`);
        if (r.impact_metric !== undefined && !isStr(r.impact_metric)) errors.push(`${label}: impact_metric must be a string`);
      }
      if (quoteRequired && (!isStr(r.quote) || r.quote.trim().length === 0 || r.quote.length > 300)) errors.push(`${label}: quote must be a short string`);
    }
  };
  checkSimple(d.education, "education", true);
  checkSimple(d.certifications, "certifications", true);
  checkSimple(d.projects, "projects", true);

  const claims = d.skill_claims;
  if (!isArr(claims)) errors.push("skill_claims must be an array");
  else {
    for (const raw of claims) {
      const c = isObj(raw) ? raw : null;
      if (!c) {
        errors.push("skill_claims: entry must be an object");
        return;
      }
      if (!isStr(c.skill) || c.skill.trim().length === 0 || c.skill.length > 80) errors.push("skill_claims: skill missing/too long");
      if (c.years !== undefined && (!isNum(c.years) || c.years < 0 || c.years > 50)) errors.push("skill_claims: years out of bounds");
      if (!isStr(c.proficiency_tier) || !TIERS.includes(c.proficiency_tier)) errors.push(`skill_claims: proficiency_tier must be one of ${TIERS.join(",")}`);
      if (!isStr(c.quote) || c.quote.trim().length === 0 || c.quote.length > 300) errors.push("skill_claims: quote must be a short string");
      if (!isStr(c.association) || !["explicit", "inferred", "unsupported"].includes(c.association)) {
        errors.push("skill_claims: association must be explicit|inferred|unsupported");
      }
    }
  }
  if (!isArr(d.ambiguities)) errors.push("ambiguities must be an array");
  if (!isArr(d.conflicts)) errors.push("conflicts must be an array");
  return fail(errors);
}


// ---------------------------------------------------------------------------
// Phase 7 policy-context helpers — pure, testable:
//  - who may see whose employee context (server-side authorization)
//  - resolving an employee mention inside a question
// ---------------------------------------------------------------------------

export interface CallerView {
  id: string;
  role: string;
  org_id: string;
}

export interface EmployeeView {
  id: string;
  org_id: string;
  name: string;
  manager_id: string | null;
  work_location?: string | null;
  worker_type?: string | null;
  role?: string | null;
}

/** Employees can see themselves; HR roles see everyone in the org; managers
 *  see their direct reports. Never decided on the client. */
export function canViewEmployee(caller: CallerView, target: EmployeeView): boolean {
  if (target.org_id !== caller.org_id) return false;
  if (target.id === caller.id) return true;
  if (["hr_executive", "hr_partner", "recruiter"].includes(caller.role)) return true;
  if (caller.role === "manager" && target.manager_id === caller.id) return true;
  return false;
}

/** Phase 9 (item 18): the "Employee" selector only offers people the caller may
 *  view AND who are actual employees/managers — candidates and service users
 *  (e.g. IT security personas) are never selectable as employees. */
export function employeeSelectorOptions(employees: EmployeeView[], caller: CallerView): EmployeeView[] {
  return (employees ?? []).filter(
    (e) => canViewEmployee(caller, e) && (e.role === "employee" || e.role === "manager" || e.id === caller.id)
  );
}

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Find a visible employee whose first name appears as a whole word in the
 *  question. Deterministic; only returns employees the caller may view. */
export function findEmployeeMention(
  question: string,
  employees: EmployeeView[],
  caller: CallerView
): EmployeeView | null {
  const q = String(question ?? "").toLowerCase();
  for (const emp of employees) {
    if (!canViewEmployee(caller, emp)) continue;
    const first = (emp.name.split(/\s+/)[0] ?? "").toLowerCase();
    if (!first || first.length < 2) continue;
    const re = new RegExp(`(^|\\W)${escapeRegExp(first)}(\\W|$)`, "i");
    if (re.test(q)) return emp;
  }
  return null;
}


// ---------------------------------------------------------------------------
// WorkSense deterministic leave engine (Phase 7).
// Matches POL-LVE v2 ("Leave & Time Off Policy"): 24 days/year, credited
// monthly at 2 days per full month of service; up to 3 days carryover;
// public holidays at the applicable location do not reduce the balance;
// mid-year joiners accrue only for months employed in the leave year.
// Zero LLM — every number is computed, so answers can cite the policy while
// the arithmetic stays honest and unit-tested.
// ---------------------------------------------------------------------------

export const LEAVE_POLICY = {
  days_per_year: 24,
  monthly_credit: 2,
  carryover_cap_days: 3,
  notice_days_for_long_leave: 28, // 4 weeks for requests of 10+ consecutive days
  long_leave_threshold: 10,
} as const;

export const LEAVE_YEAR_START = { month: 0, day: 1 }; // 1 January

/** Whole calendar months between two dates (join/start to as-of). A month
 *  counts when the same day-of-month has passed in the following month. */
export function fullMonthsBetween(from: string, to: string): number {
  const a = new Date(from);
  const b = new Date(to);
  if (Number.isNaN(a.getTime()) || Number.isNaN(b.getTime()) || b < a) return 0;
  let months = (b.getUTCFullYear() - a.getUTCFullYear()) * 12 + (b.getUTCMonth() - a.getUTCMonth());
  if (b.getUTCDate() < a.getUTCDate()) months -= 1;
  return Math.max(0, months);
}

/** Full months of employment inside the current leave year. */
export function monthsInLeaveYear(joinDate: string, asOf: string): number {
  const yearStart = `${new Date(asOf).getUTCFullYear()}-01-01`;
  if (new Date(joinDate) > new Date(asOf)) return 0;
  const effectiveStart = new Date(joinDate) > new Date(yearStart) ? joinDate : yearStart;
  return fullMonthsBetween(effectiveStart, asOf);
}

export interface LeaveSummary {
  accrued_days: number;
  taken_days: number;
  unused_days: number;
  carryover_days: number;
  carryover_cap_days: number;
  monthly_credit: number;
  as_of: string;
  join_date: string;
}

/** Deterministic balance for an employee on an as-of date. */
export function leaveSummary(params: { join_date: string; taken_days: number; as_of: string }): LeaveSummary {
  const accrued = LEAVE_POLICY.monthly_credit * fullMonthsBetween(params.join_date, params.as_of);
  const unused = Math.max(0, accrued - params.taken_days);
  const carryover = Math.min(LEAVE_POLICY.carryover_cap_days, unused);
  return {
    accrued_days: accrued,
    taken_days: params.taken_days,
    unused_days: unused,
    carryover_days: carryover,
    carryover_cap_days: LEAVE_POLICY.carryover_cap_days,
    monthly_credit: LEAVE_POLICY.monthly_credit,
    as_of: params.as_of,
    join_date: params.join_date,
  };
}

/** A leave request spanning public holidays consumes only non-holiday days. */
export function leaveDaysConsumed(params: { from: string; to: string; public_holidays: string[] }): {
  calendar_days: number;
  holiday_days: number;
  leave_days_consumed: number;
} {
  const from = new Date(params.from);
  const to = new Date(params.to);
  if (Number.isNaN(from.getTime()) || Number.isNaN(to.getTime()) || to < from) {
    return { calendar_days: 0, holiday_days: 0, leave_days_consumed: 0 };
  }
  const holidays = new Set(
    (params.public_holidays ?? []).map((d) => d.slice(0, 10))
  );
  let calendarDays = 0;
  let holidayDays = 0;
  const cursor = new Date(from);
  while (cursor <= to) {
    const iso = cursor.toISOString().slice(0, 10);
    if (holidays.has(iso)) holidayDays += 1;
    calendarDays += 1;
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  return {
    calendar_days: calendarDays,
    holiday_days: holidayDays,
    leave_days_consumed: Math.max(0, calendarDays - holidayDays),
  };
}


